describe('Account Deletion - Password Confirmation', () => {
  beforeEach(() => {
    cy.visit('/account/settings');
  });

  it('should successfully delete account after confirming password', () => {
    // Verify account settings page is visible
    cy.get('[data-testid="account-settings-page"]').should('be.visible');

    // Click on delete account button
    cy.get('[data-testid="delete-account-button"]').click();

    // Verify confirmation modal appears
    cy.get('[data-testid="delete-account-modal"]').should('be.visible');
    cy.get('[data-testid="confirm-password-input"]').should('be.visible');

    // Enter correct password
    cy.get('[data-testid="confirm-password-input"]').type('ValidPassword123');

    // Click confirm delete button
    cy.get('[data-testid="confirm-delete-button"]').click();

    // Verify success message is displayed
    cy.get('[data-testid="account-deleted-success-message"]').should('be.visible');
    cy.get('[data-testid="account-deleted-success-message"]').should('contain', 'Your account has been deleted');

    // Verify user is redirected to login page
    cy.url().should('include', '/login');
  });

  it('should not delete account when password confirmation fails', () => {
    // Verify account settings page is visible
    cy.get('[data-testid="account-settings-page"]').should('be.visible');

    // Click on delete account button
    cy.get('[data-testid="delete-account-button"]').click();

    // Verify confirmation modal appears
    cy.get('[data-testid="delete-account-modal"]').should('be.visible');
    cy.get('[data-testid="confirm-password-input"]').should('be.visible');

    // Enter incorrect password
    cy.get('[data-testid="confirm-password-input"]').type('WrongPassword123');

    // Click confirm delete button
    cy.get('[data-testid="confirm-delete-button"]').click();

    // Verify error message is displayed
    cy.get('[data-testid="password-mismatch-error"]').should('be.visible');
    cy.get('[data-testid="password-mismatch-error"]').should('contain', 'Incorrect password');

    // Verify account is NOT deleted (modal remains open)
    cy.get('[data-testid="delete-account-modal"]').should('be.visible');

    // Verify user is still on settings page
    cy.url().should('include', '/account/settings');
  });
});
